# WAR — fire-and-forget tick (returns 202 instantly; batched collector) — fixes cron timeout
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-fast-tick.ps1
$ErrorActionPreference = 'Stop'
if (-not (Test-Path 'src\product\intel')) { New-Item -ItemType Directory -Force -Path 'src\product\intel' | Out-Null }
if (-not (Test-Path 'src\api')) { New-Item -ItemType Directory -Force -Path 'src\api' | Out-Null }

# ---- src/product/intel/intelBuilder.ts ----
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'src\product\intel\intelBuilder.ts'), [Convert]::FromBase64String($b64))
Write-Host '  wrote src/product/intel/intelBuilder.ts' -ForegroundColor Green

# ---- src/api/wiredApp.ts ----
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'src\api\wiredApp.ts'), [Convert]::FromBase64String($b64))
Write-Host '  wrote src/api/wiredApp.ts' -ForegroundColor Green

Write-Host 'Then: npm run build; git add -A; git commit -m "fast tick"; git push' -ForegroundColor Cyan